package cloud.treenewbee.quizforge.hub.ai;

import java.net.*;
import java.net.http.*;
import java.nio.file.*;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.*;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.annotation.DirtiesContext;
import org.springframework.test.context.*;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import tools.jackson.databind.json.JsonMapper;
import cloud.treenewbee.quizforge.hub.account.AccountCrypto;
import cloud.treenewbee.quizforge.hub.storage.HubDatabase;
import static cloud.treenewbee.quizforge.hub.storage.HubDatabase.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;

@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"ADMIN_ENABLED=true","HUB_DEVICE_CONNECT_ENABLED=true","OFFICIAL_AI_MASTER_KEY=AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=","logging.level.root=WARN"})
@DirtiesContext(classMode=DirtiesContext.ClassMode.AFTER_CLASS)
class AiHttpTest {
    static final Path ROOT;static{try{ROOT=Files.createTempDirectory("qfh-java-ai-");}catch(Exception e){throw new ExceptionInInitializerError(e);}}
    static final JsonMapper JSON=JsonMapper.builder().build();static final String PASSWORD="synthetic-admin-password";
    @DynamicPropertySource static void data(DynamicPropertyRegistry registry){registry.add("hub.data-dir",ROOT::toString);}
    @Autowired HubDatabase db;@Autowired AiCrypto crypto;@Autowired AccountCrypto passwords;@MockitoBean AiTransport transport;@Value("${local.server.port}") int port;
    final HttpClient client=HttpClient.newBuilder().followRedirects(HttpClient.Redirect.NEVER).build();String admin,user,cookie,adminCookie,device;
    @BeforeEach void seed(){reset(transport);db.transaction(c->{update(c,"DELETE FROM ai_upstreams");update(c,"INSERT INTO official_ai_config(id,enabled,model,daily_limit,monthly_tokens,updated) VALUES(1,1,'synthetic',0,0,0) ON CONFLICT(id) DO UPDATE SET enabled=1");return null;});admin=account(true);user=account(false);adminCookie=cookie(admin);cookie=cookie(user);device="qfd_"+AccountCrypto.urlToken();db.transaction(c->{update(c,"INSERT INTO connect_devices VALUES(?,?,?,?,?,?,?,0)",UUID.randomUUID().toString(),user,AccountCrypto.sha(device),"Synthetic","web",Instant.now().toString(),System.currentTimeMillis());update(c,"INSERT INTO ai_points VALUES(?,?,?)",user,100,System.currentTimeMillis());return null;});}
    String account(boolean admin){String id=UUID.randomUUID().toString(),hash=admin?passwords.password(PASSWORD):"!disabled";db.transaction(c->{update(c,"INSERT INTO users VALUES(?,?,?,?,?,?)",id,id+"@example.test","Synthetic",hash,admin?1:0,Instant.now().toString());return null;});return id;}
    String cookie(String id){String raw=AccountCrypto.token();db.transaction(c->{update(c,"INSERT INTO sessions VALUES(?,?,?)",AccountCrypto.sha(raw),id,System.currentTimeMillis()+3600000);return null;});return "qfh_session="+raw;}
    String base(){return "http://127.0.0.1:"+port;}
    HttpRequest request(String path,String method,Object body,String cookie,String bearer){var r=HttpRequest.newBuilder(URI.create(base()+path)).header("Origin",base());if(cookie!=null)r.header("Cookie",cookie);if(bearer!=null)r.header("Authorization","Bearer "+bearer);if(body!=null)r.header("Content-Type","application/json");return r.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(JSON.writeValueAsString(body))).build();}
    HttpResponse<byte[]> call(String path,String method,Object body,String cookie,String bearer)throws Exception{return client.send(request(path,method,body,cookie,bearer),HttpResponse.BodyHandlers.ofByteArray());}
    Map<String,Object> value(HttpResponse<byte[]> response){assertEquals(200,response.statusCode(),new String(response.body()));return JSON.readValue(response.body(),Map.class);}
    Map<String,Object> completion(){return Map.of("model","quizforge-official","messages",List.of(Map.of("role","user","content","synthetic")),"max_tokens",100,"stream",false);}
    AiTransport.Result answer(){return new AiTransport.Result(200,Map.of("choices",List.of(Map.of("message",Map.of("role","assistant","content","synthetic answer"),"finish_reason","stop")),"usage",Map.of("prompt_tokens",100,"completion_tokens",50,"total_tokens",150)));}
    String upstream(int position){String id=UUID.randomUUID().toString(),key="synthetic-upstream-key-"+position;db.transaction(c->{long now=System.currentTimeMillis();update(c,"INSERT INTO ai_upstreams(id,seq,position,note,base_url,model,key_cipher,key_hint,input_price,output_price,remaining,enabled,status,created,updated) VALUES(?,?,?,?,?,?,?,?,?,?,?,1,'ok',?,?)",id,position,position,"synthetic","https://model"+position+".example.test/v1","synthetic-model",crypto.encrypt(key,AiCrypto.KEY_AAD),"syn…key",10000,20000,100,now,now);return null;});return id;}
    @Test void successfulDeviceCallChargesExactlyOnceWithoutExposingSecrets()throws Exception{String key=upstream(1);when(transport.call(anyString(),anyString(),anyMap(),eq(90))).thenReturn(answer());var result=value(call("/api/ai/v1/chat/completions","POST",completion(),null,device));assertEquals(2,((Number)((Map<?,?>)result.get("quizforge")).get("cost")).intValue());assertEquals(98L,(long)db.read(c->number(row(c,"SELECT balance FROM ai_points WHERE user_id=?",user).get("balance"))));assertEquals(2L,(long)db.read(c->number(row(c,"SELECT spent FROM ai_upstreams WHERE id=?",key).get("spent"))));assertFalse(JSON.writeValueAsString(result).contains("upstream-key"));var status=value(call("/api/admin/official-ai","GET",null,adminCookie,null));assertFalse(JSON.writeValueAsString(status).contains("key_cipher"));assertFalse(JSON.writeValueAsString(status).contains("synthetic-upstream-key"));}
    @Test void upstreamFailuresDoNotChargeAndFallbackUsesTheAnsweringKey()throws Exception{String first=upstream(1),second=upstream(2);when(transport.call(contains("model1"),anyString(),anyMap(),eq(90))).thenReturn(new AiTransport.Result(503,Map.of()));when(transport.call(contains("model2"),anyString(),anyMap(),eq(90))).thenReturn(answer());value(call("/api/ai/v1/chat/completions","POST",completion(),null,device));assertEquals("fault",db.read(c->row(c,"SELECT status FROM ai_upstreams WHERE id=?",first).get("status")));assertEquals(0L,(long)db.read(c->number(row(c,"SELECT spent FROM ai_upstreams WHERE id=?",first).get("spent"))));assertEquals(2L,(long)db.read(c->number(row(c,"SELECT spent FROM ai_upstreams WHERE id=?",second).get("spent"))));when(transport.call(anyString(),anyString(),anyMap(),eq(90))).thenThrow(new IllegalStateException("synthetic failure"));assertEquals(502,call("/api/ai/v1/chat/completions","POST",completion(),null,device).statusCode());assertEquals(98L,(long)db.read(c->number(row(c,"SELECT balance FROM ai_points WHERE user_id=?",user).get("balance"))));}
    @Test void authenticationDisabledServiceAndInvalidImagesFailBeforeNetwork()throws Exception{upstream(1);assertEquals(401,call("/api/ai/v1/chat/completions","POST",completion(),cookie,null).statusCode());var invalid=new LinkedHashMap<String,Object>(completion());invalid.put("messages",List.of(Map.of("role","user","content",List.of(Map.of("type","image_url","image_url",Map.of("url","https://untrusted.example/image.png"))))));assertEquals(400,call("/api/ai/v1/chat/completions","POST",invalid,null,device).statusCode());invalid.put("messages",List.of(Map.of("content","no role")));assertEquals(400,call("/api/ai/v1/chat/completions","POST",invalid,null,device).statusCode());verifyNoInteractions(transport);value(call("/api/admin/official-ai","PUT",Map.of("enabled",false),adminCookie,null));assertEquals(404,call("/api/ai/v1/chat/completions","POST",completion(),null,device).statusCode());}
    @Test void codesAreEncryptedRedeemedOnceAndBalanceAdjustmentIsAudited()throws Exception{long expires=System.currentTimeMillis()+86400000;var response=call("/api/admin/ai-codes","POST",Map.of("count",1,"amount",1000,"expires",expires,"note","synthetic"),adminCookie,null);assertEquals(201,response.statusCode());var item=JSON.readTree(response.body()).get("items").get(0);String code=item.get("code").asText(),id=item.get("id").asText();String cipher=db.read(c->row(c,"SELECT code_cipher FROM ai_redeem_codes WHERE id=?",id).get("code_cipher").toString());assertNotEquals(code,cipher);assertEquals(code,crypto.decrypt(cipher,AiCrypto.CODE_AAD));var redeemed=value(call("/api/connect/redeem","POST",Map.of("code","\u00a0"+code.toLowerCase(Locale.ROOT)+"\uFEFF"),null,device));assertEquals(1100,((Number)redeemed.get("balance")).intValue());assertEquals(400,call("/api/connect/redeem","POST",Map.of("code",code),null,device).statusCode());assertEquals(409,call("/api/admin/ai-codes/"+id,"PUT",Map.of("enabled",true),adminCookie,null).statusCode());value(call("/api/admin/users/"+user+"/ai-balance","PUT",Map.of("balance",1234,"reason","synthetic adjustment"),adminCookie,null));assertEquals(1234,((Number)value(call("/api/account/ai","GET",null,cookie,null)).get("balance")).intValue());assertEquals(2L,(long)db.read(c->number(row(c,"SELECT COUNT(*) n FROM ai_points_ledger WHERE user_id=?",user).get("n"))));}
    @Test void addingKeysRequiresPasswordAndExistingAddressCannotBeChanged()throws Exception{when(transport.call(anyString(),anyString(),anyMap(),eq(20))).thenReturn(answer());var body=new LinkedHashMap<String,Object>(Map.of("baseUrl","https://model.example.test/v1","model","synthetic","apiKey","synthetic-write-only-key","inputPrice",10000,"outputPrice",20000,"password","wrong"));assertEquals(403,call("/api/admin/ai-keys","POST",body,adminCookie,null).statusCode());body.put("password",PASSWORD);var added=call("/api/admin/ai-keys","POST",body,adminCookie,null);assertEquals(201,added.statusCode(),new String(added.body()));String id=JSON.readTree(added.body()).get("item").get("id").asText();assertFalse(new String(added.body()).contains("synthetic-write-only-key"));assertEquals(400,call("/api/admin/ai-keys/"+id,"PUT",Map.of("baseUrl","https://other.example.test"),adminCookie,null).statusCode());assertEquals(400,call("/api/admin/ai-keys/order","PUT",Map.of("ids",List.of(id,id)),adminCookie,null).statusCode());value(call("/api/admin/ai-keys/"+id+"/enabled","PUT",Map.of("enabled",false),adminCookie,null));assertTrue(((List<?>)value(call("/api/admin/official-ai","GET",null,adminCookie,null)).get("keys")).size()>0);}
    @Test void concurrentCallsAreBoundedAndBalanceNeverGoesNegative()throws Exception{upstream(1);db.transaction(c->{update(c,"UPDATE ai_points SET balance=1 WHERE user_id=?",user);return null;});var started=new CountDownLatch(2);var release=new CountDownLatch(1);when(transport.call(anyString(),anyString(),anyMap(),eq(90))).thenAnswer(i->{started.countDown();assertTrue(release.await(10,TimeUnit.SECONDS));return answer();});var first=client.sendAsync(request("/api/ai/v1/chat/completions","POST",completion(),null,device),HttpResponse.BodyHandlers.ofByteArray());var second=client.sendAsync(request("/api/ai/v1/chat/completions","POST",completion(),null,device),HttpResponse.BodyHandlers.ofByteArray());try{assertTrue(started.await(10,TimeUnit.SECONDS));assertEquals(429,call("/api/ai/v1/chat/completions","POST",completion(),null,device).statusCode());}finally{release.countDown();}assertEquals(200,first.get(10,TimeUnit.SECONDS).statusCode());assertEquals(200,second.get(10,TimeUnit.SECONDS).statusCode());assertEquals(0L,(long)db.read(c->number(row(c,"SELECT balance FROM ai_points WHERE user_id=?",user).get("balance"))));assertEquals(1L,(long)db.read(c->number(row(c,"SELECT SUM(points) n FROM official_ai_usage WHERE user_id=?",user).get("n"))));}
    @Test void internalAiRejectsPublicHostAndCookieCannotReplaceDeviceToken()throws Exception{var request=HttpRequest.newBuilder(URI.create("http://localhost:"+port+"/internal/ai/me")).header("Cookie",cookie).GET().build();assertEquals(403,client.send(request,HttpResponse.BodyHandlers.ofByteArray()).statusCode());assertEquals(200,call("/internal/ai/me","GET",null,cookie,null).statusCode());assertEquals(401,call("/api/connect/me","GET",null,cookie,null).statusCode());}
    @AfterAll static void cleanup()throws Exception{try(var paths=Files.walk(ROOT)){for(var path:paths.sorted(Comparator.reverseOrder()).toList())Files.deleteIfExists(path);}}
}
